-- headhunterAI 은행 배포 파일: question_bank 29행 (app.bank_seed export로 생성, 직접 고치지 않음)
INSERT INTO question_bank (category, subcategory, text, source, dup_group)
SELECT category, subcategory, text, source, dup_group FROM jsonb_to_recordset($bank$[{"category": "personality", "subcategory": "협업", "text": "팀 프로젝트에서 의견이 충돌했을 때 어떻게 조율했는지 한 가지 사례를 들어 설명해 주세요.", "source": "db", "dup_group": "p-conflict"}, {"category": "personality", "subcategory": "협업", "text": "동료와 의견이 달랐던 경험과 그때 본인이 맡은 역할을 설명해 주세요.", "source": "db", "dup_group": "p-conflict"}, {"category": "personality", "subcategory": "책임감", "text": "맡은 일에서 예상하지 못한 문제가 생겼을 때 끝까지 해결한 경험을 설명해 주세요.", "source": "db", "dup_group": "p-ownership"}, {"category": "personality", "subcategory": "성장", "text": "최근 1년 동안 스스로 학습해서 익힌 기술이나 지식과 그 방법을 설명해 주세요.", "source": "db", "dup_group": "p-growth"}, {"category": "personality", "subcategory": "성장", "text": "실패했던 경험에서 무엇을 배웠고 이후 어떻게 다르게 행동했는지 설명해 주세요.", "source": "db", "dup_group": "p-failure"}, {"category": "personality", "subcategory": "소통", "text": "비전문가에게 기술적인 내용을 설명해야 했던 경험과 그때 쓴 방법을 설명해 주세요.", "source": "db", "dup_group": "p-communication"}, {"category": "personality", "subcategory": "문제해결", "text": "제한된 시간 안에 여러 일을 처리해야 했을 때 우선순위를 어떻게 정했는지 설명해 주세요.", "source": "db", "dup_group": "p-priority"}, {"category": "personality", "subcategory": "윤리", "text": "데이터나 AI 결과를 다룰 때 윤리적으로 고민했던 상황이 있다면 설명해 주세요.", "source": "db", "dup_group": "p-ethics"}, {"category": "company", "subcategory": "지원동기", "text": "우리 회사에 지원한 이유와 입사 후 하고 싶은 일을 설명해 주세요.", "source": "db", "dup_group": "c-motive"}, {"category": "company", "subcategory": "지원동기", "text": "이 직무에 지원하게 된 계기를 설명해 주세요.", "source": "db", "dup_group": "c-motive-role"}, {"category": "company", "subcategory": "동기/지원 이유", "text": "우리 회사의 서비스나 사업 중 관심 있는 부분과 그 이유를 설명해 주세요.", "source": "db", "dup_group": "c-interest"}, {"category": "company", "subcategory": "조직 문화 적합성", "text": "본인이 일하기 좋은 팀 문화는 어떤 모습이고, 그 안에서 어떤 역할을 하고 싶은지 설명해 주세요.", "source": "db", "dup_group": "c-culture"}, {"category": "company", "subcategory": "조직 문화 적합성", "text": "빠르게 변하는 환경에서 일했던 경험과 그때 적응한 방법을 설명해 주세요.", "source": "db", "dup_group": "c-change"}, {"category": "job", "subcategory": "머신러닝", "text": "과적합이 무엇인지 설명하고, 이를 줄이기 위해 써 본 방법을 한 가지 설명해 주세요.", "source": "db", "dup_group": "j-overfit"}, {"category": "job", "subcategory": "머신러닝", "text": "정밀도와 재현율의 차이를 설명하고, 어떤 상황에서 재현율을 더 중시하는지 예를 들어 주세요.", "source": "db", "dup_group": "j-pr"}, {"category": "job", "subcategory": "머신러닝", "text": "학습 데이터와 실제 서비스 데이터의 분포가 달라졌을 때 어떻게 감지하고 대응할지 설명해 주세요.", "source": "db", "dup_group": "j-drift"}, {"category": "job", "subcategory": "딥러닝", "text": "트랜스포머의 셀프 어텐션이 어떤 문제를 해결하는지 설명해 주세요.", "source": "db", "dup_group": "j-attention"}, {"category": "job", "subcategory": "딥러닝", "text": "학습이 잘 되지 않을 때 확인하는 순서를 설명해 주세요.", "source": "db", "dup_group": "j-debug-train"}, {"category": "job", "subcategory": "딥러닝", "text": "배치 정규화의 역할과 추론 시 동작 차이를 설명해 주세요.", "source": "db", "dup_group": "j-bn"}, {"category": "job", "subcategory": "LLM·RAG", "text": "RAG 시스템에서 검색 품질이 낮을 때 개선할 수 있는 방법을 한 가지 설명해 주세요.", "source": "db", "dup_group": "j-rag"}, {"category": "job", "subcategory": "LLM·RAG", "text": "LLM이 사실과 다른 답을 만드는 문제를 줄이기 위해 시스템 차원에서 할 수 있는 방법을 설명해 주세요.", "source": "db", "dup_group": "j-hallucination"}, {"category": "job", "subcategory": "LLM·RAG", "text": "프롬프트 엔지니어링과 파인튜닝 중 하나를 선택해야 할 때의 기준을 설명해 주세요.", "source": "db", "dup_group": "j-ft"}, {"category": "job", "subcategory": "컴퓨터 비전", "text": "객체 탐지 모델의 성능을 평가할 때 mAP가 무엇을 의미하는지 설명해 주세요.", "source": "db", "dup_group": "j-map"}, {"category": "job", "subcategory": "데이터 사이언스", "text": "결측치가 많은 데이터를 다룰 때의 처리 방법과 선택 기준을 설명해 주세요.", "source": "db", "dup_group": "j-missing"}, {"category": "job", "subcategory": "데이터 사이언스", "text": "A/B 테스트 결과를 해석할 때 주의할 점을 한 가지 설명해 주세요.", "source": "db", "dup_group": "j-ab"}, {"category": "job", "subcategory": "파이썬", "text": "파이썬에서 리스트와 제너레이터의 차이와 대용량 데이터 처리 시 선택 기준을 설명해 주세요.", "source": "db", "dup_group": "j-generator"}, {"category": "job", "subcategory": "MLOps", "text": "모델을 서비스에 배포한 뒤 모니터링해야 할 지표를 설명해 주세요.", "source": "db", "dup_group": "j-monitor"}, {"category": "job", "subcategory": "MLOps", "text": "온프레미스 GPU 서버에서 LLM 추론 비용과 지연 시간을 줄이는 방법을 한 가지 설명해 주세요.", "source": "db", "dup_group": "j-serving"}, {"category": "job", "subcategory": "AX", "text": "현업 업무 하나를 AI로 자동화한다면 무엇을 고르고 어떤 순서로 진행할지 설명해 주세요.", "source": "db", "dup_group": "j-ax"}]$bank$::jsonb) AS x(category text, subcategory text, text text, source text, dup_group text)
WHERE NOT EXISTS (SELECT 1 FROM question_bank t WHERE t.category IS NOT DISTINCT FROM x.category AND t.text IS NOT DISTINCT FROM x.text);
